                M.invoke("Fusery", "FinishReveal")
                S.fused += 1
                return true
            end
            for i = 1, 3 do M.invoke("Fusery", "EjectPet", g[i]) end
            return false
        end
    end
    return false
end
function F.upgrades()
    if os.clock() - F.lastUp < 2 then return end
    F.lastUp = os.clock()
    local s = M.save()
    local money = tonumber(s.Money) or 0
    local keep = tonumber(val("u_keep", "0")) or 0
    if on("u_base") then
        local lv = tonumber(s.BaseUpgradeLevel) or 0
        local maxLv = 0
        pcall(function() maxLv = D.Bases.GetMaxBaseLevel() end)
        local cfg
        pcall(function() cfg = D.Bases.GetBaseConfigFor(lv + 1) end)
        if (maxLv == 0 or lv < maxLv) and type(cfg) == "table" and tonumber(cfg.Cost) and money - keep >= cfg.Cost then
            M.fire("Homestead", "AskBaseTierRaise")
            S.upgrades += 1
            money -= cfg.Cost
            task.wait(0.5)
        end
    end
    if on("u_tread") then
        local lv = tonumber(s.TreadmillUpgradeLevel) or 1
        local ord = {}
        pcall(function() ord = D.Tread.GetOrdered() end)
        local nx = ord[lv + 1]
        if type(nx) == "table" and tonumber(nx.Price) and money - keep >= nx.Price then
            if M.invoke("Treadmill", "AskTierRaise", nx._id) then S.upgrades += 1 money -= nx.Price end
        end
    end
    if on("u_trail") then
        local owned = {}
        for k, v in pairs(s.TrailInventory or {}) do owned[type(k) == "string" and k or tostring(v)] = true end
        local have = 0
        local best
        pcall(function()
            for id, t in pairs(D.Trails.Directory) do
                local m = tonumber(t.SpeedMultiplier) or 0
                if owned[id] then have = math.max(have, m)
                elseif type(t) == "table" and t.DisplayInShop ~= false and tonumber(t.Price) and money - keep >= t.Price then
                    if not best or m > (tonumber(best.SpeedMultiplier) or 0) then best = t end
                end
            end
        end)
        if best and (tonumber(best.SpeedMultiplier) or 0) > have and (F.trailBad[best._id] or 0) < os.clock() then
            if M.invoke("Trailwear", "AskPurchase", best._id) then
                M.invoke("Trailwear", "AskChoose", best._id)
                S.upgrades += 1
            else
                F.trailBad[best._id] = os.clock() + 120
            end
        end
    end
end
task.spawn(function()
    task.wait(2)
    while RUNNING do
        local ok, err = pcall(function()
            if not M.alive() then S.task = __T["Waiting to respawn"] task.wait(1) return end
            if on("f_hatch") and F.hatch() then return end
            if on("f_plant") and F.plant() then return end
            if on("f_equip") then F.equip() end
            if on("f_steal") then
                local inv = M.count(M.save().EggInventory)
                local backlog = #F.unplaced()
                local cap = tonumber(val("s_backlog", 10)) or 10
                if inv < F.invMax - 1 and (backlog < cap or os.clock() >= F.plantFull) then
                    if backlog < cap and os.clock() >= (F.waitBetter or 0) and F.steal() then return end
                end
                S.task = inv >= F.invMax - 1 and __T["Egg inventory full"] or __T["Waiting for better eggs (field resets every 5 min)"]
                if on("t_ride") then F.ride() end
            else
                S.task = __T["Stealing paused (F6)"]
                if on("t_ride") then F.ride() S.task = __T["Riding treadmill"] end
            end
        end)
        if not ok then LOG("loop", err) end
        task.wait(0.2)
    end
end)
