function F.findAfk()
    if F.afkFn ~= nil then return F.afkFn end
    F.afkFn = false
    pcall(function()
        if type(getgc) ~= "function" then return end
        for _, f in ipairs(getgc()) do
            if type(f) == "function" then
                local ok, name, src = pcall(debug.info, f, "ns")
                if ok and name == "markActive" and type(src) == "string" and src:find("AntiAFK", 1, true) then
                    F.afkFn = f
                    break
                end
            end
        end
    end)
    return F.afkFn
end
